import{_ as i,o as a,c as o,at as e}from"./chunks/framework.CY22Hent.js";const b=JSON.parse('{"title":"系统分析师笔记01_绪论","description":"","frontmatter":{"title":"系统分析师笔记01_绪论","date":"2026-08-10T00:00:00.000Z","lastUpdated":"2026-08-10T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/系统分析师笔记01_绪论.md","filePath":"blogs/软考/系统分析师笔记01_绪论.md"}'),t={name:"blogs/软考/系统分析师笔记01_绪论.md"};function p(r,l,u,n,c,s){return a(),o("div",null,[...l[0]||(l[0]=[e('<p>[toc]</p><h1 id="系统分析师笔记01-绪论" tabindex="-1">系统分析师笔记01_绪论 <a class="header-anchor" href="#系统分析师笔记01-绪论" aria-label="Permalink to &quot;系统分析师笔记01_绪论&quot;">​</a></h1><p>该笔记内容来自《系统分析师教程》第2版。</p><h2 id="信息与信息系统" tabindex="-1">信息与信息系统 <a class="header-anchor" href="#信息与信息系统" aria-label="Permalink to &quot;信息与信息系统&quot;">​</a></h2><p>信息是一种客观事物，它与材料、能源一样，都是社会的基础资源。</p><p>1948年，美国科学家香农(C.E.Shannon)在对通信理论深入研究的基础上，提出了信息的概念，创立了信息理论。此后，人们对信息的研究迅速增加，形成了一个新的学科:信息论。</p><p>至今，信息论已发展成一个内涵非常丰富的学科，与控制论和系统论并称为现代科学的“三论”。</p><h3 id="信息的基本概念" tabindex="-1">信息的基本概念 <a class="header-anchor" href="#信息的基本概念" aria-label="Permalink to &quot;信息的基本概念&quot;">​</a></h3><p>人们通过深入研究，发现信息还具有很多其他的特征，列举如下:</p><blockquote><p>信息的特征</p></blockquote><ul><li>(1)客观性。信息是客观事物在人脑中的反映，而反映的对象则有主观和客观的区别，因此，信息可分为主观信息(例如，决策、指令和计划等)和客观信息(例如，国际形势、经济发展和一年四季等)。主观信息必然要转化成客观信息，例如，决策和计划等主观信息要转化成实际行动。因此，信息具有客观性。</li><li>(2)普遍性。物质的普遍性决定了信息的普遍存在。</li><li>(3)无限性。客观世界是无限的，反映客观世界的信息自然也是无限的。</li><li>(4)动态性。信息是随着时间的变化而变化的。</li><li>(5)相对性。不同的个体从同一事物中获取的信息及信息量可能是不同的。</li><li>(6)依附性。信息的依附性可以从两个方面来理解。 <ul><li>一方面，信息是客观世界的反映，任何信息必然由客观事物所产生，不存在无源的信息;</li><li>另一方面，任何信息都要依附于一定的载体存在，需要有物质的承担者，信息不能完全脱离物质而独立存在。</li></ul></li><li>(7)变换性。信息通过处理可以实现变换或转换，使其形式和内容发生变化，以适应特定的需要。</li><li>(8)传递性。信息在时间上的传递就是存储，空间上的传递就是转移或扩散。</li><li>(9)层次性。客观世界是分层次的，反映客观世界的信息自然也是分层次的。</li><li>(10)系统性。信息可以表示为一种集合，不同类别的信息可以形成不同的整体。因此，可以形成与现实世界相对应的信息系统。</li><li>(11)转化性。信息的产生不能没有物质，信息的传递不能没有能量，但有效地使用信息，可以将信息转化为物质或能量。</li></ul><blockquote><p>信息的功能</p></blockquote><p>在人类认识世界和改造世界的过程中，信息与物质、能源一样，发挥着十分重要的作用。</p><p>信息的主要功能如下：</p><ul><li>(1)为认识世界提供依据。人们认识世界，首先要获取认识对象的有关信息，并通过对这些信息的加工获得有关知识，从而形成正确的认识。</li><li>(2)为改造世界提供指导。人们认识世界的目的是改造世界，而改造世界就必须有正确的观念作指导。这些观念包括活动的计划、环境分析、结果的预测和发展变化的对策等，这些都离不开信息的指导。</li><li>(3)为有序的建立提供保证。人们所有活动的目的都是使得客观世界变得更加有序。这需要信息的保证。</li><li>(4)为资源开发提供条件。人类社会的生存和发展要建立在资源的开发和利用上。信息可以帮助人们识别和利用资源，从而提高资源的利用效率。</li><li>(5)为知识的生产提供材料。</li></ul><h3 id="系统及其相关理论" tabindex="-1">系统及其相关理论 <a class="header-anchor" href="#系统及其相关理论" aria-label="Permalink to &quot;系统及其相关理论&quot;">​</a></h3><p>系统是由相互联系、相互依赖、相互作用的事物或过程组成的具有整体功能和综合行为的统一体。例如，经济领域中的商业系统和金融系统，自然界中的水利系统和生态系统等。</p><p>从数学角度来看，系统是一个集合，是由许多相互作用、相互依存的事物(集合元素)为了达到某个目标组成的集合。</p><p>研究系统的一般理论和方法称为系统论。</p><blockquote><p>系统论的任务</p></blockquote><p>系统论的任务不仅在于认识系统的特点和规律，更重要的还在于利用这些特点和规律去控制、管理、改造或创造系统，使得系统的存在、发展更符合人们的需要。也就是说，研究系统的目的在于调整系统结构，协调各元素的关系，使系统达到优化目标。</p><blockquote><p>系统论的作用</p></blockquote><p>(1) 改变人类的思维方式。系统论的出现，使人类的思维方式发生了深刻的变化。以往研究问题，一般是将事物分解成若干部分，抽象出最简单的因素，然后再以部分的性质去说明复杂事物。这是传统的分析方法，这种方法的着眼点在局部或元素，遵循的是单项因果决定论，虽然这是数百年来在特定范围内行之有效、人们最熟悉的思维方法，但是它不能如实地说明事物的整体性，不能反映事物之间的联系和相互作用，它只适用于认识较为简单的事物，而不能胜任对复杂问题的研究。</p><p>在现代科学的整体化和高度综合化的发展趋势下，在人类面临的许多规模巨大、关系复杂、参数众多的复杂问题面前，它就显得无能为力了。而系统分析方法能够站在较高的层次上认识问题，从而做到高屋建瓴、纵观全局，为解决复杂问题提供了有效的思维方式。所以，系统论连同控制论、信息论等其他学科一起，为人类认识世界提供了新的思路和新的方法，从而促进了各门学科的发展。</p><p>(2) 提供科学的理论和方法。系统论反映了现代科学发展的趋势和现代社会化大生产的特点，以及现代社会生活的复杂性，所以它的理论和方法能够得到广泛的应用。系统论不仅为现代科学的发展提供了理论和方法，而且也为解决现代社会中的政治、经济、军事、科学和文化等领域的各种复杂问题提供了方法论的基础，系统观念已经渗透到每个领域。</p><p>(3) 形成统一的系统科学体系。当前，系统论发展的趋势和方向是朝着建立统一的系统科学体系的目标前进。一般系统论创始人贝塔朗菲(L.Bertalanffy)，将他的系统论分为两个部分，分别是狭义系统论和广义系统论。狭义系统论着重对系统本身进行分析与研究;广义系统论则是对一类相关的系统科学原理进行分析与研究，其中包括系统科学、系统技术和系统哲学 三方面的内容。</p><h3 id="系统工程方法论" tabindex="-1">系统工程方法论 <a class="header-anchor" href="#系统工程方法论" aria-label="Permalink to &quot;系统工程方法论&quot;">​</a></h3><p>系统工程是从整体出发合理开发、设计、实施和运用系统科学的工程技术。</p><p>它根据总体协调的需要，综合应用自然科学和社会科学中的有关思想、理论和方法，利用计算机作为工具，对系统的结构、元素、信息和反馈等进行分析，以达到最优规划、最优设计、最优管理和最优控制的目的。</p><p>系统工程方法论是指运用系统工程研究问题的一套程序化的工作方法和策略，也可以理解成为了达到预期目标，运用系统工程思想和技术解决问题的工作程序或步骤。</p><h3 id="信息系统工程" tabindex="-1">信息系统工程 <a class="header-anchor" href="#信息系统工程" aria-label="Permalink to &quot;信息系统工程&quot;">​</a></h3><p>信息系统工程是以系统工程的方法来实现信息系统建设的过程，它是用系统工程的原理、方法来指导信息系统建设与管理的一门工程技术学科。</p><p>信息系统工程是系统工程的一个分支学科，因此，系统工程的原理、方法、技术和过程都适用于它。同时，信息系统与一般的系统相比，又有其自身的专业特征，这就决定了信息系统工程在研究方法上具有整体性，在技术应用上具有综合性，在工程管理上具有科学性。</p><blockquote><p>信息系统的生命周期</p></blockquote><p>信息系统与其他事物一样，也要经历产生、发展、成熟和消亡的过程。信息系统从产生到消亡的整个过程称为信息系统的生命周期。</p><p>一般来说，信息系统的生命周期可分为5个阶段如下所示。</p><ul><li>(1)系统规划。信息系统规划是系统建设的起始阶段，其作用是指明信息系统在企业经营战略中的作用和地位，指导信息系统的开发。一个比较完整的系统规划应当包括信息系统的开发目标、总体架构、组织结构和管理流程、实施计划和技术规范等。</li><li>(2)系统分析。系统分析阶段的目标是为系统设计阶段提供系统的逻辑模型，其主要任务是在可行性分析和总体规划的基础上，对现有系统进行进一步的详细调查，并整理成规范的文档资料;</li><li>(3)系统设计。系统设计是信息系统开发过程的另一个重要阶段。在这一阶段，要根据系统分析的结果，设计出信息系统的实施方案，从而为开发人员提供清晰而完整的物理设计说明。</li><li>(4)系统实现。系统实现阶段的任务是将设计文档变成能在计算机上运行的软件系统。</li><li>(5)系统运行与维护。系统投入运行后，需要经常进行维护和评价，记录系统运行的情况，根据一定的规格对系统进行必要的修改，评价系统的工作质量和经济效益。</li></ul><h2 id="系统分析师" tabindex="-1">系统分析师 <a class="header-anchor" href="#系统分析师" aria-label="Permalink to &quot;系统分析师&quot;">​</a></h2><p>信息系统的开发是一项复杂的系统工程，这是因为一个信息系统的建立，往往要投入大量的人力、物力和财力，同时需要大量的时间。</p><p>在开发过程中，需要将系统中的各构成要素、组织结构、信息交换和反馈控制等有机地组织起来，以求得最佳的系统方案。</p><p>因此，一个信息系统的成功建设是团队共同创造的结果，而在这个团队中，核心人物就是系统分析师。</p><h3 id="系统分析师的角色定位" tabindex="-1">系统分析师的角色定位 <a class="header-anchor" href="#系统分析师的角色定位" aria-label="Permalink to &quot;系统分析师的角色定位&quot;">​</a></h3><p>系统分析师在信息系统建设中处于重要地位，根据不同的需要，他们可能身兼多种角色。</p><p>一名优秀的系统分析师既要是IT专家，又要是管理业务专家。具体来说，系统分析师的角色包括以下几种:</p><ul><li>(1) <strong>IT专家</strong>。系统分析师首要的角色应是IT专家。信息系统具有极大的复杂性，仅从技术的角度来看，会用到复杂的软件、硬件、通信和网络技术;同时，由于IT产品和技术的更新换代速度极快，为保证信息系统开发成功并健康地运行，企业必须从应用的角度认识问题，对市场上的新产品和新技术有正确的评估与选择。因此，成为IT领域某一个或几个方面的专家，是对系统分析师的基本要求。</li><li>(2) <strong>管理业务专家</strong>。企业信息系统的建设是一个极为复杂的管理系统工程，它的成功不仅取决于信息技术的科学、合理应用，更为重要的是它还涉及企业的各项管理业务、员工素质、领导的认识能力和决策能力，以及其他方方面面的因素。因此，系统分析师要有丰富的管理业务方面的知识和经验，才能领导好信息系统的建设工作，也就是说，系统分析师在成为IT专家的同时，还要成为管理业务专家。</li><li>(3) <strong>IT人员和非IT人员的沟通者</strong>。IT人员和非IT人员之间存在着无形的隔阂。很多信息系统建设项目的失败，就是因为这种隔阂所造成的。由于系统分析师既是IT专家，又是管理业务专家，因此，他们可以作为IT人员和非IT人员的沟通桥梁。</li><li>(4) <strong>对外谈判者</strong>。现代社会的一个最大特点就是社会分工越来越细，专业化程度越来越高。现在已经很少有企业可以单凭自己的组织队伍开发本企业的信息系统了，较普遍的做法是将开发工作委托给专业的开发组织，或在条件具备时直接购买商品化软件。但是，这样一来，就要面临如何与专业开发组织“讨价还价”的问题。特别是在企业领导不懂信息技术的情况下，很可能使企业处于被动地位。这时，正是系统分析师发挥作用的时候，因为他们代表企业利益，同时又是IT专家，由他们与专业组织“过招”，就会得心应手。由系统分析师担任对外部专业组织的谈判代表，是比较恰当的选择。</li><li>(5) <strong>信息系统运行的指导者</strong>。信息系统的价值在于它的运行，只有能够健康、平稳、安全地运行的信息系统才是好的信息系统，而要做到这些，就必须做好系统的运行管理、评价和维护，以及系统升级、功能扩展和再工程。系统运行管理牵涉技术、业务和人员，以及制度与规范建设等方面。所有这些问题都应是系统分析师所特别关注和思考的，也就是说，系统分析师应当成为信息系统运行的指导者，从纲领和细节两个方面指导信息系统按要求正常运行。</li><li>(6) <strong>信息系统建设项目的技术负责人</strong>。从建设单位的角度而言，企业信息化是“一把手工程”，也就是说，整个信息系统建设项目的负责人应由企业高层领导担任，而项目的技术负责人应该是系统分析师;从承建单位的角度而言，开发项目的负责人应由信息系统项目管理师担任，由系统分析师担任技术经理或研发经理。因为信息系统建设项目往往比较多地涉及具体技术问题和业务问题，这些问题的解决对整个项目的成功起着关键作用。</li></ul><h3 id="系统分析师的任务" tabindex="-1">系统分析师的任务 <a class="header-anchor" href="#系统分析师的任务" aria-label="Permalink to &quot;系统分析师的任务&quot;">​</a></h3><blockquote><p>信息化战略管理中的任务</p></blockquote><p>系统分析师在信息化战略管理中担负着重要任务，主要体现在以下几个方面:</p><ul><li>(1)深入理解企业的发展战略目标和业务发展方向，并在此基础上明确企业战略对信息化的需求。</li><li>(2)对企业内外部信息化环境、企业所处行业的信息化水平，以及企业信息化现状进行分析和评估。</li><li>(3)与企业高层领导和管理人员一起设计和确定企业信息系统建设的长期目标，还要对目标进行必要的分解。</li><li>(4)能够主持制定企业信息化战略规划。</li></ul><blockquote><p>信息化基础建设中的任务</p></blockquote><p>系统分析师在企业信息化基础建设中担负着重要任务，主要体现在以下几个方面:</p><ul><li>(1)对计算机系统的发展概况、系统配置和性能有较为清楚的了解，要对计算机系统的投资和成本等有较为清楚、准确的估算，对系统性能/价格比有恰当的把握。</li><li>(2)对计算机网络技术有较好的了解和把握，从企业的实际出发，对企业的网络建设做出可行性分析报告，提出科学、合理的建设方案。</li><li>(3)负责信息系统安全制度和规范的制定，指导系统安全的运行和管理，协调和处理系统安全的有关问题，负责就系统安全的情况和问题进行分析与论证，并向有关部门或领导报告工作。</li><li>(4)能够设计出信息系统的评价体系，包括评价指标、评价方法、评价程序、评价主体和客体，以及评价结果的使用等。</li><li>(5)能够主持制定信息化管理制度，对信息化管理制度的适用性进行动态分析，并做出相应调整。</li><li>(6)能够审定企业信息化各种标准规范，制定企业信息化标准规范体系，协调和处理企业信息化标准规范实施中的重大问题。</li></ul><h2 id="系统分析师的知识体系" tabindex="-1">系统分析师的知识体系 <a class="header-anchor" href="#系统分析师的知识体系" aria-label="Permalink to &quot;系统分析师的知识体系&quot;">​</a></h2><p>系统分析师属于复合型人才，知识体系是由其担任的角色和工作任务决定的。</p><ul><li>首先，系统分析师必须非常熟悉信息系统的建设，这要求其掌握相当多的信息技术，即技术知识与技能;</li><li>其次，系统分析师需要与各种各样的人交互，进行这些交互需要具备很多良好的素质和技能，可以归纳为经营管理知识与技能;</li><li>再次，系统分析师需要熟悉其工作的行业，这要求具备较多的业务领域知识，即业务知识与技能;</li><li>最后，也是最重要的，系统分析师必须具备高尚的人格和道德修养。</li></ul><blockquote><p>技术知识与技能</p></blockquote><p>系统分析师作为IT专家，应具备丰富的专业技术知识和技能，包括计算机系统、计算机科学与技术、计算机网络、系统安全、信息系统工程、数学及相关学科、经济管理等方面的知识。</p><blockquote><p>经营管理知识与技能</p></blockquote><p>在现实生活中，经营是运营、运作之意;管理是指通过决策、计划、组织、领导、控制和创新等职能的发挥来分配、协调一切可以调用的资源，以实现单独的个人无法实现的目标。</p><p>在经营和管理方面，系统分析师需要具有以下知识:</p><ul><li>(1)人际沟通知识。系统分析师应该能够有效地和他人沟通，包括口头沟通和书面沟通。</li><li>(2)人际关系知识。由于系统分析师需要与系统开发中的其他人员交互，因此，系统分析师需要具备良好的处理人际关系的能力，以便很好地和其他人员协调开展工作。</li><li>(3)项目管理知识。系统分析师作为信息系统项目中的技术负责人，必须熟悉信息系统项目管理知识，包括项目管理的理论、方法和相关工具。</li><li>(4)企业管理知识。系统分析师要对企业战略管理、知识管理和日常运作管理有较深入的了解和较深刻的认识，以便制订企业信息化战略，建立企业业务模型，进行企业业务流程改进或重组。</li><li>(5)市场营销知识。根据工作性质不同，系统分析师有时候需要担任谈判者的角色，有时需要担任销售者的角色。</li></ul><blockquote><p>业务知识与技能</p></blockquote><p>系统分析师的业务知识情况极为复杂，它与系统分析师的个人专业出身和职业经历，以及供职单位的业务特点和岗位职责等有关。</p><p>例如，如果某系统分析师供职于保险公司，他就应当掌握一定的保险业务知识。</p><p>对于供职于IT企业的系统分析师而言，每次承接的项目可能属于不同的行业，因此，需要系统分析师具有很强的学习能力，能够快速熟悉用户业务领域的专业知识，由外行迅速转变为“业内人士”。</p><blockquote><p>人文修养</p></blockquote><p>人文修养是指人所具备的高尚的道德品质、健康的生活态度，以及坚韧的意志和宽广的胸怀的形成、发展和提升过程，是人生阅历、生活经验、道德情操和人文知识的积淀、内化的结果。一个人的人文修养是思想境界升华和科学文化滋养的综合发展过程，是知和行的统一。</p>',67)])])}const d=i(t,[["render",p]]);export{b as __pageData,d as default};
